e</h2></div><a href="<?=legacy_base_url('produk')?>">Belanja Lagi</a></div><?php if($orders):?><div class="account-order-list"><?php foreach($orders as $o):?><a class="account-order" href="<?=legacy_base_url('pesanan/'.rawurlencode($o['order_number']))?>?token=<?=rawurlencode($o['public_token'])?>"><div><span><?=e($o['order_number'])?></span><b><?=e(marketplace_order_status_label((string)$o['order_status']))?></b><small><?=e(date('d M Y H:i',strtotime($o['created_at'])))?> • <?=e(strtoupper($o['courier_code']).' '.$o['courier_service'])?></small></div><strong><?=rupiah($o['grand_total'])?></strong><i class="bi bi-chevron-right"></i></a><?php endforeach;?></div><?php else:?><div class="account-empty"><i class="bi bi-bag"></i><h3>Belum ada pesanan</h3><p>Pesanan marketplace yang dibuat setelah login akan muncul di sini.</p></div><?php endif;?></section></div></section></main>
